#!/bin/bash
set -e
cd ~/workspace
mkdir -p ~/workspace/_fixscripts/patches

echo "=================================================="
echo " LOCATING TARGET FILES"
echo "=================================================="
BATCH_TSX=$(find . -iname "BatchManagerUltra.tsx" -not -path "*/node_modules/*" | head -1)
SERIES_TSX=$(find . -iname "TestSeriesManagerUltra.tsx" -not -path "*/node_modules/*" | head -1)
EXAMLIST_ROUTE=$(find . -path "*/routes/examListing.js" -not -path "*/node_modules/*" | head -1)

for f in "BATCH_TSX:$BATCH_TSX" "SERIES_TSX:$SERIES_TSX" "EXAMLIST_ROUTE:$EXAMLIST_ROUTE"; do
  name="${f%%:*}"; path="${f#*:}"
  if [ -z "$path" ]; then echo "❌ $name NOT FOUND — aborting patches for this file"; else echo "✅ $name → $path"; fi
done
echo ""
echo "=================================================="
echo " WRITING PATCH BLOBS "
echo "=================================================="
cat > ~/workspace/_fixscripts/patches/batch_p7_old.b64 << 'B64EOF'

B64EOF
base64 -d ~/workspace/_fixscripts/patches/batch_p7_old.b64 > ~/workspace/_fixscripts/patches/batch_p7_old.txt
cat > ~/workspace/_fixscripts/patches/batch_p7_new.b64 << 'B64EOF'

B64EOF
base64 -d ~/workspace/_fixscripts/patches/batch_p7_new.b64 > ~/workspace/_fixscripts/patches/batch_p7_new.txt
cat > ~/workspace/_fixscripts/patches/series_p7_old.b64 << 'B64EOF'

B64EOF
base64 -d ~/workspace/_fixscripts/patches/series_p7_old.b64 > ~/workspace/_fixscripts/patches/series_p7_old.txt
cat > ~/workspace/_fixscripts/patches/series_p7_new.b64 << 'B64EOF'

B64EOF
base64 -d ~/workspace/_fixscripts/patches/series_p7_new.b64 > ~/workspace/_fixscripts/patches/series_p7_new.txt
cat > ~/workspace/_fixscripts/patches/backend_quickedit2_old.b64 << 'B64EOF'

B64EOF
base64 -d ~/workspace/_fixscripts/patches/backend_quickedit2_old.b64 > ~/workspace/_fixscripts/patches/backend_quickedit2_old.txt
cat > ~/workspace/_fixscripts/patches/backend_quickedit2_new.b64 << 'B64EOF'

B64EOF
base64 -d ~/workspace/_fixscripts/patches/backend_quickedit2_new.b64 > ~/workspace/_fixscripts/patches/backend_quickedit2_new.txt
cat > ~/workspace/_fixscripts/patches/backend_clone2_old.b64 << 'B64EOF'

B64EOF
base64 -d ~/workspace/_fixscripts/patches/backend_clone2_old.b64 > ~/workspace/_fixscripts/patches/backend_clone2_old.txt
cat > ~/workspace/_fixscripts/patches/backend_clone2_new.b64 << 'B64EOF'

B64EOF
base64 -d ~/workspace/_fixscripts/patches/backend_clone2_new.b64 > ~/workspace/_fixscripts/patches/backend_clone2_new.txt

echo "=================================================="
echo " APPLYING PATCHES (Node.js exact-match replace, NOT sed -i, per Rule C2)"
echo "=================================================="
cat > ~/workspace/_fixscripts/apply_patches.js << 'NODEEOF'
const fs = require('fs');

function applyPatch(label, targetFile, oldFile, newFile) {
  if (!targetFile) { console.log(`⏭️  ${label} — target file not found, skipped`); return false; }
  try {
    const content = fs.readFileSync(targetFile, 'utf8');
    const oldText = fs.readFileSync(oldFile, 'utf8').replace(/\n$/, '');
    const newText = fs.readFileSync(newFile, 'utf8').replace(/\n$/, '');
    const count = content.split(oldText).length - 1;
    if (count === 0) {
      console.log(`⚠️  ${label} — exact pattern NOT FOUND. This usually means the previous fix script wasn't run yet, or the file was edited since. Skipped — will not touch this file for this patch.`);
      return false;
    }
    if (count > 1) {
      console.log(`⚠️  ${label} — pattern found ${count} times (expected 1, ambiguous). Skipped for safety.`);
      return false;
    }
    const updated = content.replace(oldText, newText);
    fs.writeFileSync(targetFile, updated, 'utf8');
    console.log(`✅ ${label} — applied`);
    return true;
  } catch (e) {
    console.log(`❌ ${label} — error: ${e.message}`);
    return false;
  }
}

const P = process.env.HOME + '/workspace/_fixscripts/patches/';
const BATCH_TSX = process.env.BATCH_TSX;
const SERIES_TSX = process.env.SERIES_TSX;
const EXAMLIST_ROUTE = process.env.EXAMLIST_ROUTE;

console.log('--- BatchManagerUltra.tsx ---');
applyPatch('Batch P7 (fix /api/exams-manage URL + Duration field + Unlimited toggle)', BATCH_TSX, P+'batch_p7_old.txt', P+'batch_p7_new.txt');

console.log('');
console.log('--- TestSeriesManagerUltra.tsx ---');
applyPatch('Series P7 (fix /api/exams-manage URL + Duration field + Unlimited toggle)', SERIES_TSX, P+'series_p7_old.txt', P+'series_p7_new.txt');

console.log('');
console.log('--- examListing.js (backend) ---');
applyPatch('Backend quick-edit v2 (duration-based endTime auto-calc)', EXAMLIST_ROUTE, P+'backend_quickedit2_old.txt', P+'backend_quickedit2_new.txt');
applyPatch('Backend clone-advanced v2 (duration-based endTime auto-calc)', EXAMLIST_ROUTE, P+'backend_clone2_old.txt', P+'backend_clone2_new.txt');
NODEEOF

BATCH_TSX="$BATCH_TSX" SERIES_TSX="$SERIES_TSX" EXAMLIST_ROUTE="$EXAMLIST_ROUTE" node ~/workspace/_fixscripts/apply_patches.js

echo ""
echo "=================================================="
echo " CLEANUP + COMMIT + PUSH"
echo "=================================================="
rm -rf ~/workspace/_fixscripts

git status --short
git add -A
git commit -m "Fix: Edit/Copy modal CTA buttons were calling wrong API prefix (/api/exams instead of /api/exams-manage), causing silent failure. Also replaced End Date/Time field with auto-calculated Duration field, and added Unlimited Attempts toggle." || echo "ℹ️ Nothing to commit"
git push origin main

echo ""
echo "--- DONE: Pushed. Frontend (Vercel) + Backend (Render) will auto-redeploy in a couple minutes. ---"
